import pandas as pd

# ---------------------------------------------------------
# PULS ETECH - SYNTHETIC ICU DEMO DATASET
# 12 patients × 4 time points = 48 records
# ---------------------------------------------------------

records = []


def add_patient(patient_id, age, values, sepsis_values):
    """
    Add 4 time points for one patient.
    values = [heart_rate, systolic_bp, spo2, respiratory_rate, temperature, lactate, wbc]
    """
    for i in range(4):

        heart_rate = values[i][0]
        systolic_bp = values[i][1]
        spo2 = values[i][2]
        respiratory_rate = values[i][3]
        temperature = values[i][4]
        lactate = values[i][5]
        wbc = values[i][6]

        # Approximate MAP
        map_value = systolic_bp * 0.70

        records.append({
            "patient_id": patient_id,
            "age": age,
            "time_point": i + 1,
            "heart_rate": heart_rate,
            "systolic_bp": systolic_bp,
            "spo2": spo2,
            "respiratory_rate": respiratory_rate,
            "temperature": temperature,
            "lactate": lactate,
            "wbc": wbc,
            "map": round(map_value, 1),
            "sepsis": sepsis_values[i]
        })


